// Se ejecuta con:  node --env-file=.env.local index.js

const clave = process.env.OPENAI_API_KEY

if (!clave) {
  console.error('\nFalta la clave OPENAI_API_KEY.')
  console.error('Comprueba tres cosas, en este orden:')
  console.error(' 1. Que el archivo .env.local existe en esta misma carpeta.')
  console.error(' 2. Que dentro pone OPENAI_API_KEY=algo, sin espacios alrededor del igual.')
  console.error(' 3. Que has arrancado con: node --env-file=.env.local index.js\n')
  process.exit(1)
}

console.log('Node', process.version)
console.log('Clave cargada correctamente:', clave.slice(0, 7) + '...')
console.log('Todo listo.\n')


